"/* Trail Companion — forest-at-dusk design system */
:root {
  --bg: hsl(150 30% 6%);
  --bg-2: hsl(150 25% 9%);
  --glass: hsl(150 30% 14% / 0.55);
  --glass-strong: hsl(150 30% 16% / 0.85);
  --stroke: hsl(140 40% 70% / 0.12);
  --stroke-glow: hsl(142 55% 50% / 0.35);
  --text: hsl(60 20% 94%);
  --muted: hsl(120 10% 68%);
  --moss: hsl(142 55% 50%);
  --moss-2: hsl(160 60% 38%);
  --amber: hsl(32 95% 60%);
  --ember: hsl(12 85% 58%);
  --danger: hsl(0 75% 62%);
  --radius: 22px;
  --shadow: 0 20px 60px -20px hsl(150 60% 2% / 0.8);
